void detach_mounts(struct dentry *dentry) {
    struct mount *mnt;
    struct hlist_node *node;
    struct list_head *unmounted_list;

    lock_mount_hash();
    mnt = lookup_mount(dentry);
    if (mnt) {
        lock_mount(mnt);
        unmounted_list = kmalloc(sizeof(struct list_head), GFP_KERNEL);
        INIT_LIST_HEAD(unmounted_list);

        hlist_for_each_entry(mnt, node, &mnt->hash, hlist) {
            if (mnt->flags & MNT_UMOUNT) {
                unmount_children(mnt);
                list_add_tail(&mnt->list, unmounted_list);
            } else {
                unmount_tree(mnt);
            }
        }

        unlock_mount(mnt);
        release_mount(mnt);
        kfree(unmounted_list);
    }
    unlock_mount_hash();
}

void detach_mounts(struct dentry *dentry) {
    struct mount *mount;
    struct hlist_node *node;
    struct mount *unmounted_mounts = NULL;

    lock_mount_namespace();
    mount = lookup_mount(dentry);
    if (!mount) {
        unlock_mount_namespace();
        return;
    }

    lock_mount_hash();
    hlist_for_each_entry_safe(mount, node, &mount->hlist, hlist) {
        if (mount->flags & MNT_UMOUNT) {
            unmount_child_mounts(mount);
            add_to_unmounted_list(mount, &unmounted_mounts);
        } else {
            unmount_tree(mount);
        }
    }

    unlock_mount_hash();
    release_mount(mount);
    unlock_mount_namespace();
}
